import{_ as l,l as o,o as e,c as s,v as t,p as n,x as r,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const E=JSON.parse('{"title":"租买问题","description":"","frontmatter":{"title":"租买问题","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/ski-rental.md","filePath":"cs/ski-rental.md","lastUpdated":1789023840000}'),c={name:"cs/ski-rental.md"};function b(_,a,m,T,u,A){const i=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=t('<h1 id="租买问题" tabindex="-1">租买问题 <a class="header-anchor" href="#租买问题" aria-label="Permalink to &quot;租买问题&quot;">​</a></h1><div class="epigraph"><p>每天租 1，买断代价 $b$；确定性最优是租 $b-1$ 天再买，2-竞争；随机可到 $e/(e-1)$。</p><footer>—— 据 Karlin, Manasse, Rudolph and Sleator, Competitive Snoopy Caching, 1988；租买成为在线教材原型整理</footer></div><p>上一课<a href="/cs/paging-competitive">页面置换</a>是 \\(k\\)-竞争。租买（ski rental）：未知滑雪天数 \\(T\\)。缺口是最干净的 2-竞争：阈值购买。不重写 LRU 势。后课秘书是选最大。本课 1-server 式的买 vs 租。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>离线：若 \\(T\\lt b\\) 全租，否则第一天买，代价 \\(\\min(T,b)\\)。在线不知道 \\(T\\)。确定性：某天买。最优确定性：租 \\(b-1\\) 天，第 \\(b\\) 天买，代价 \\(\\le 2\\,\\mathrm{OPT}\\)。任何确定性 \\(\\ge 2-O(1/b)\\)。随机：以几何或调和分布在天数上买，期望 \\(e/(e-1)\\approx 1.58\\)。</p><p>缺口是这一阈值，不是缓存槽。</p><h3 id="不是金融期权定价" tabindex="-1">不是金融期权定价 <a class="header-anchor" href="#不是金融期权定价" aria-label="Permalink to &quot;不是金融期权定价&quot;">​</a></h3><p>同一「何时沉没成本换所有权」的形状，本课纯竞争比。不写 Black–Scholes。</p><p><span class="marginnote">Karlin 等 1988 与 snoopy caching。教材把 ski-rental 当 2-竞争原型。后课秘书问题。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>确定性写清阈值。随机：给出分布与期望分析要点（对 oblivious）。自适应对手随机无优势。</p>',11)),(e(),n(h,null,{default:r(()=>[p(i,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20DAY%5B%22%E6%9C%AA%E7%9F%A5%E5%A4%A9%E6%95%B0%20T%22%5D%20--%3E%20RENT%5B%22%E6%8C%89%E5%A4%A9%E7%A7%9F%22%5D%0A%20%20RENT%20--%3E%20BUY%5B%22%E7%AC%AC%20b%20%E5%A4%A9%E4%B9%B0%22%5D%0A%20%20BUY%20--%3E%20TWO%5B%222-%E7%AB%9E%E4%BA%89%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>买断后代价不再涨。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>最坏 \\(T=b\\)：在线付 \\(b-1+b=2b-1\\)，OPT 付 \\(b\\)。更长 \\(T\\) 双方都付 \\(b\\) 量级。随机把质量摊在可能的 \\(T\\) 上。与分页：租买是 \\(k=1\\) 的某种极限直觉，不要硬等同。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写多件设备、不写利率。后课默认：未知使用时长买 vs 租，确定性 2。下一课秘书问题。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>确定性租 \\(b-1\\) 再买，2-竞争。</li><li>随机 \\(e/(e-1)\\)。</li><li>离线 \\(\\min(T,b)\\)。</li><li>出处：Karlin, Manasse, Rudolph and Sleator, 1988。</li></ul>',7))])}const k=l(c,[["render",b]]);export{E as __pageData,k as default};
